const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const canberra = ee.Geometry.Point([149.13, -35.28]);
  const startDate = '2020-01-14';
  const endDate = '2020-01-23'; // Exclusive end date
  const inches_threshold = 8;
  const mm_threshold = inches_threshold * 25.4; // 203.2 mm

  // 2. Data Acquisition & Check
  // Using CHIRPS daily precipitation
  let collection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(canberra);

  const count = collection.size().getInfo();
  console.log(`Images found: ${count}`);

  if (count === 0) {
    console.log("No precipitation data found for the date range.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum all precipitation
  const totalPrecip = collection.select('precipitation').sum();

  // 4. Calculate total rainfall at the point
  const result = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canberra,
    scale: 5566,
    maxPixels: 1e9
  }).getInfo();

  const precipMm = result.precipitation;

  // Check for valid pixels
  const pixelCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canberra,
    scale: 5566,
    maxPixels: 1e9
  }).getInfo().precipitation;

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Validation & Final Answer
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (precipMm < 0) {
    console.log("Invalid precipitation value (negative).");
    console.log("<answer>C3</answer>");
    return;
  }

  const precipInches = precipMm / 25.4;
  console.log(`Total rainfall: ${precipMm.toFixed(2)} mm (${precipInches.toFixed(2)} inches)`);
  console.log(`Threshold: ${inches_threshold} inches (${mm_threshold.toFixed(2)} mm)`);

  if (precipInches >= inches_threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
